/**
 * @module features/tv-dashboard/model/useTvDashboardData
 *
 * Hook principal da Torre de Controle da Operação (painel TV `/tv`).
 *
 * Paraleliza as fontes de dados via React Query:
 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
 * - comparativos: vs DIA ANTERIOR (principal, v3 — base pró-rateada p/ canal
 *   live) e vs MESMO DIA da semana passada (secundário);
 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
 * - alertas de estoque NOMEADOS (`estoque` × `produtos_master.ativo = true`,
 *   restritos ao setor de produtos vendáveis — `TV_ALERT_SETOR`);
 * - heartbeat + FEED nomeado de movimentações (`movimentacoes` de hoje);
 * - perdas no período do filtro global (`perdas`, R$ + itens + delta);
 * - compras no período (`notas_fiscais`, "gasto até hoje" + delta);
 * - produção da fábrica (`daily_production` com loja_id NULL).
 *
 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
 * defasado; tipo "Fabrica" = card de fábrica).
 */

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type {
  TvComprasSummary,
  TvDateRange,
  TvException,
  TvFactoryData,
  TvFactoryProduction,
  TvFreshness,
  TvMovementSummary,
  TvNetworkSummary,
  TvPerdasSummary,
  TvPeriod,
  TvRecentMove,
  TvSalesChannel,
  TvSalesSnapshot,
  TvStoreData,
  TvExceptionsResult,
} from './types';
import {
  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
  TV_FACTORY_HOURS,
  TV_MINI_FEED_SIZE,
  addDays,
  aggregateCompras,
  aggregateMovements,
  aggregatePerdas,
  buildFreshness,
  buildNoMovementException,
  buildRecentMoves,
  buildStockExceptions,
  buildStockSummary,
  classifyStoreRag,
  fetchAllPages,
  parseIsoDateLocal,
  pctOfFullDayTarget,
  pctOfProRataTarget,
  periodRange,
  previousPeriodRange,
  proRataDayBase,
  rangeToLocalDayBounds,
  relativeDelta,
  remapFlashLojaIds,
  sortAndLimitExceptions,
  sortCriticalItems,
  toIsoDateLocal,
  weekOverWeekDelta,
  type ComprasByLoja,
  type FlashRow,
  type MovementAggregate,
  type MovementFeedRow,
  type PerdasAggregate,
  type PerdasByLoja,
  type StockDetail,
  type StockRow,
} from './tvMath';
import { useMinuteClock } from './useMinuteClock';

// ─────────────────────────────────────────────────────────────────────────────
// Query keys + intervalos (exportados para o useTvRealtime invalidar)
// ─────────────────────────────────────────────────────────────────────────────

/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
export const tvDashboardKeys = {
  all: ['tv-dashboard'] as const,
  context: () => [...tvDashboardKeys.all, 'context'] as const,
  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
  /** Vendas de referência Degust (ontem + mesmo dia da semana passada). */
  referenceSales: () => [...tvDashboardKeys.all, 'reference-sales'] as const,
  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
  /** Feed nomeado de movimentações de hoje (mini-feed "AGORA"). */
  movementFeed: () => [...tvDashboardKeys.all, 'movement-feed'] as const,
  /** Prefixo das perdas (invalidar TODOS os períodos de uma vez). */
  perdasRoot: () => [...tvDashboardKeys.all, 'perdas'] as const,
  perdas: (period: TvPeriod) => [...tvDashboardKeys.perdasRoot(), period] as const,
  /** Prefixo das compras (invalidar TODOS os períodos de uma vez). */
  comprasRoot: () => [...tvDashboardKeys.all, 'compras'] as const,
  compras: (period: TvPeriod) => [...tvDashboardKeys.comprasRoot(), period] as const,
  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
  /** Prefixo do drill-down por loja (invalidar todas as lojas/ranges). */
  storeDetailRoot: () => [...tvDashboardKeys.all, 'store-detail'] as const,
  storeDetail: (lojaId: number, range: TvDateRange) =>
    [...tvDashboardKeys.storeDetailRoot(), lojaId, range.from, range.to] as const,
};

// ─────────────────────────────────────────────────────────────────────────────
// Filtros canônicos de NF de compra (mesmo critério do módulo notas-fiscais)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Status de NF que CONTAM como compra — mesmo critério do DRE
 * (`features/financeiro/ui/DREReport.tsx`): tudo menos `erro`. O campo de
 * data canônico é `data_nota` (emissão), idem DRE e filtro "data da nota"
 * da página de NFs.
 */
export const NF_COUNTED_STATUSES = ['processada', 'processando'] as const;

/**
 * NFs de transferência interna (fornecedor "Momma Doces") NÃO são compra —
 * mesma exclusão da lista do módulo notas-fiscais (transferência ≠ NF de
 * compra; pertencem à aba Transferências).
 */
export const NF_TRANSFER_SUPPLIER_PATTERN = '%momma doces%';

/** Intervalos de atualização (ms) por classe de dado. */
export const TV_QUERY_INTERVALS = {
  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
  liveMs: 60_000,
  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
  slowMs: 300_000,
} as const;

// ─────────────────────────────────────────────────────────────────────────────
// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
// ─────────────────────────────────────────────────────────────────────────────

/** Loja ativa carregada no contexto do painel. */
export interface TvLoja {
  id: number;
  nome: string;
  tipo: string | null;
}

/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
export interface TvContext {
  lojas: TvLoja[];
  /** Lojas com venda live (existem em `degust_stores`). */
  degustLojaIds: Set<number>;
  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
  degustCodeToLoja: Map<number, number>;
  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
  linxLojaIds: number[];
  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
  factoryLojaId: number | null;
}

function isFactoryTipo(tipo: string | null): boolean {
  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
}

/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
export async function fetchTvContext(): Promise<TvContext> {
  const [lojasRes, degustRes] = await Promise.all([
    supabase
      .from('lojas')
      .select('id, nome, tipo')
      .eq('ativo', true)
      .order('id'),
    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
  ]);
  if (lojasRes.error) throw lojasRes.error;
  if (degustRes.error) throw degustRes.error;

  const lojas: TvLoja[] = lojasRes.data ?? [];
  const degustLojaIds = new Set<number>();
  const degustCodeToLoja = new Map<number, number>();
  for (const row of degustRes.data ?? []) {
    degustLojaIds.add(row.loja_id);
    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
  }

  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
  const linxLojaIds = lojas
    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
    .map((l) => l.id);

  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
}

// ─────────────────────────────────────────────────────────────────────────────
// Vendas live (edge degust-pos-financial / flash-vendas)
// ─────────────────────────────────────────────────────────────────────────────

/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
interface DegustPosFinancialResponse {
  flash?: Array<{
    loja_id: number;
    nome_loja: string;
    total_vendas: number;
    total_cupons: number;
    ticket_medio: number;
    qtd_produtos: number;
    caixa_aberto: boolean;
    ultima_atualizacao: string | null;
  }>;
}

async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
  const today = toIsoDateLocal(new Date());
  const { data, error } = await supabase.functions.invoke<DegustPosFinancialResponse>(
    'degust-pos-financial',
    { body: { startDate: today, endDate: today } },
  );
  if (error) throw error;
  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
    loja_id: f.loja_id,
    nome_loja: f.nome_loja,
    total_vendas: f.total_vendas,
    total_cupons: f.total_cupons,
    ticket_medio: f.ticket_medio,
    caixa_aberto: f.caixa_aberto,
    ultima_atualizacao: f.ultima_atualizacao,
  }));
  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
}

// ─────────────────────────────────────────────────────────────────────────────
// Vendas defasadas (Linx via historico_vendas — último dia disponível)
// ─────────────────────────────────────────────────────────────────────────────

interface LaggedSales {
  lojaId: number;
  /** Último dia com venda registrada (YYYY-MM-DD). */
  dataReferencia: string;
  valor: number;
  quantidade: number;
  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
  valorSemanaAnterior: number | null;
  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
  valorDiaAnterior: number | null;
}

async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
  // 1) Último dia com dado para a loja
  const { data: latest, error: latestErr } = await supabase
    .from('historico_vendas')
    .select('data')
    .eq('loja_id', lojaId)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return null;

  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));

  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
  //    comparativo PRINCIPAL v3; mesma semana = secundário)
  const [curRes, weekRes, dayRes] = await Promise.all([
    supabase
      .from('historico_vendas')
      .select('valor_total, quantidade')
      .eq('loja_id', lojaId)
      .eq('data', refDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', weekAgoDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', dayBeforeDate)
      .limit(2000),
  ]);
  if (curRes.error) throw curRes.error;
  if (weekRes.error) throw weekRes.error;
  if (dayRes.error) throw dayRes.error;

  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
  const quantidade = (curRes.data ?? []).reduce(
    (s, r) => s + (r.quantidade ?? 0),
    0,
  );
  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
    const list = rows ?? [];
    return list.length > 0
      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
      : null;
  };

  return {
    lojaId,
    dataReferencia: refDate,
    valor,
    quantidade,
    valorSemanaAnterior: sumOrNull(weekRes.data),
    valorDiaAnterior: sumOrNull(dayRes.data),
  };
}

async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
  return results.filter((r): r is LaggedSales => r !== null);
}

// ─────────────────────────────────────────────────────────────────────────────
// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
// passada (secundário) — uma única query em degust_vendas_diarias
// ─────────────────────────────────────────────────────────────────────────────

interface DegustReferenceSales {
  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
  yesterday: Map<number, number>;
  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
  lastWeek: Map<number, number>;
}

async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
  const yesterday = new Map<number, number>();
  const lastWeek = new Map<number, number>();
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return { yesterday, lastWeek };
  const now = new Date();
  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('degust_vendas_diarias')
      .select('loja_id, valor_total, data')
      .in('data', [yesterdayDate, lastWeekDate])
      .in('loja_id', ids)
      .order('id')
      .range(from, to),
  );
  for (const row of rows) {
    const target = row.data === yesterdayDate ? yesterday : lastWeek;
    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
  }
  return { yesterday, lastWeek };
}

// ─────────────────────────────────────────────────────────────────────────────
// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMetas(): Promise<Map<string, number>> {
  const { data, error } = await supabase
    .from('metas_vendas')
    .select('loja_id, dia_semana, valor_meta')
    .limit(1000);
  if (error) throw error;
  const out = new Map<string, number>();
  for (const row of data ?? []) {
    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
  }
  return out;
}

function metaFor(
  metas: Map<string, number> | undefined,
  lojaId: number,
  date: Date,
): number | null {
  if (!metas) return null;
  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
// ─────────────────────────────────────────────────────────────────────────────

/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
export async function fetchStockAlerts(): Promise<StockRow[]> {
  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
  //
  // `setor` vai junto no select: a regra do CTO 2026-06-05 (alertas SÓ do
  // setor TV_ALERT_SETOR = produtos vendáveis) é aplicada client-side com
  // normalização em `buildStockSummary` — a caixa/acento no banco é
  // inconsistente ("CÂMARA FRIA" vs "Câmara Fria"), então um `.eq` server-side
  // exato deixaria variantes legítimas de "Produtos" passarem/caírem errado.
  const data = await fetchAllPages((from, to) =>
    supabase
      .from('estoque')
      .select(
        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo, setor)',
      )
      .eq('produto_master.ativo', true)
      .gt('quantidade_minima', 0)
      .or('oculto.is.null,oculto.eq.false')
      .order('id')
      .range(from, to),
  );
  return data.map((row) => ({
    loja_id: row.loja_id,
    quantidade_atual: row.quantidade_atual,
    quantidade_minima: row.quantidade_minima,
    produtoNome: row.produto_master?.nome ?? '(sem nome)',
    setor: row.produto_master?.setor ?? null,
  }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Movimentações de hoje (heartbeat por loja)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  // Pico real >1k movimentações/dia: paginar (PostgREST corta em 1000).
  const data = await fetchAllPages((from, to) =>
    supabase
      .from('movimentacoes')
      .select('loja_id, tipo_movimentacao, data_movimentacao')
      .gte('data_movimentacao', startOfDay.toISOString())
      .order('id')
      .range(from, to),
  );
  return aggregateMovements(data);
}

// ─────────────────────────────────────────────────────────────────────────────
// Feed nomeado de movimentações de hoje (mini-feed "AGORA" por coluna)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Quantas linhas o feed busca de uma vez. NÃO pagina de propósito: é um
 * feed "AGORA" (últimas {@link TV_MINI_FEED_SIZE} por unidade) — query
 * separada dos AGREGADOS (que seguem paginados via fetchAllPages). Em dia
 * de pico (acima de 150 movimentações) uma unidade parada há muitas horas
 * pode ficar sem mini-feed — aceitável: o card já mostra "última bipagem".
 */
const TV_FEED_FETCH_LIMIT = 150;

/** Forma da linha de `movimentacoes` com o join de nome do produto. */
interface MovementFeedQueryRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
  quantidade: number | null;
  produto_master: { nome: string } | null;
}

function toFeedRows(rows: MovementFeedQueryRow[]): MovementFeedRow[] {
  // Feed mostra TODA movimentação (evento operacional aconteceu, produto
  // ativo ou não) — diferente das listas de produto, que filtram ativo=true.
  return rows.map((r) => ({
    loja_id: r.loja_id,
    tipo_movimentacao: r.tipo_movimentacao,
    data_movimentacao: r.data_movimentacao,
    quantidade: r.quantidade,
    produtoNome: r.produto_master?.nome ?? '(sem produto)',
  }));
}

async function fetchMovementFeed(): Promise<Map<number, TvRecentMove[]>> {
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  const { data, error } = await supabase
    .from('movimentacoes')
    .select(
      'loja_id, tipo_movimentacao, data_movimentacao, quantidade, produto_master:produtos_master(nome)',
    )
    .gte('data_movimentacao', startOfDay.toISOString())
    .order('data_movimentacao', { ascending: false })
    .limit(TV_FEED_FETCH_LIMIT);
  if (error) throw error;
  return buildRecentMoves(toFeedRows(data ?? []), TV_MINI_FEED_SIZE);
}

// ─────────────────────────────────────────────────────────────────────────────
// Perdas no período do filtro global (tabela `perdas`)
// ─────────────────────────────────────────────────────────────────────────────

/** Par período corrente + período anterior equivalente (comparativo). */
export interface PeriodedAggregates<T> {
  current: T;
  previous: T;
}

async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
  const bounds = rangeToLocalDayBounds(range);
  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('perdas')
      .select('loja_id, valor_estimado')
      .gte('data_identificacao', bounds.startIso)
      .lt('data_identificacao', bounds.endExclusiveIso)
      .order('id')
      .range(from, to),
  );
  return aggregatePerdas(rows);
}

async function fetchPerdasAggregates(
  period: TvPeriod,
): Promise<PeriodedAggregates<PerdasByLoja>> {
  const now = new Date();
  const [current, previous] = await Promise.all([
    loadPerdasRange(periodRange(period, now)),
    loadPerdasRange(previousPeriodRange(period, now)),
  ]);
  return { current, previous };
}

// ─────────────────────────────────────────────────────────────────────────────
// Compras no período do filtro global (notas_fiscais — "gasto até hoje")
// ─────────────────────────────────────────────────────────────────────────────

async function loadComprasRange(range: TvDateRange): Promise<ComprasByLoja> {
  // Campo de data canônico: `data_nota` (emissão) — mesmo critério do DRE.
  // Status válido = tudo menos `erro` (NF_COUNTED_STATUSES); transferências
  // internas "Momma Doces" excluídas (não são compra). Paginado: um mês de
  // NFs pode passar de 1000 linhas.
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('notas_fiscais')
      .select('loja_id, valor_total')
      .gte('data_nota', range.from)
      .lte('data_nota', range.to)
      .in('status', [...NF_COUNTED_STATUSES])
      .not('fornecedor', 'ilike', NF_TRANSFER_SUPPLIER_PATTERN)
      .order('id')
      .range(from, to),
  );
  return aggregateCompras(rows);
}

async function fetchComprasAggregates(
  period: TvPeriod,
): Promise<PeriodedAggregates<ComprasByLoja>> {
  const now = new Date();
  const [current, previous] = await Promise.all([
    loadComprasRange(periodRange(period, now)),
    loadComprasRange(previousPeriodRange(period, now)),
  ]);
  return { current, previous };
}

// ─────────────────────────────────────────────────────────────────────────────
// Produção da fábrica (daily_production com loja_id NULL = fábrica)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
  const today = toIsoDateLocal(new Date());

  const loadDay = async (date: string) => {
    const { data, error } = await supabase
      .from('daily_production')
      .select('quantity')
      .is('loja_id', null)
      .eq('date', date)
      .limit(2000);
    if (error) throw error;
    return data ?? [];
  };

  let refDate = today;
  let rows = await loadDay(today);
  if (rows.length === 0) {
    // Sem produção registrada hoje → mostra o último dia disponível
    const { data: latest, error } = await supabase
      .from('daily_production')
      .select('date')
      .is('loja_id', null)
      .lte('date', today)
      .order('date', { ascending: false })
      .limit(1);
    if (error) throw error;
    const lastDate = latest?.[0]?.date;
    if (!lastDate) return null;
    refDate = lastDate;
    rows = await loadDay(lastDate);
  }

  return {
    dataReferencia: refDate,
    itens: rows.length,
    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook principal
// ─────────────────────────────────────────────────────────────────────────────

/** Retorno do {@link useTvDashboardData}. */
export interface TvDashboardData {
  network: TvNetworkSummary | null;
  stores: TvStoreData[];
  factory: TvFactoryData | null;
  exceptions: TvExceptionsResult;
  freshness: TvFreshness;
  /** Período do filtro global aplicado a perdas/compras/comparativos. */
  period: TvPeriod;
  /** Range corrente do filtro (para rótulos na UI). */
  range: TvDateRange;
  /** Range anterior equivalente usado nos comparativos. */
  previousRange: TvDateRange;
  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
  isLoading: boolean;
  /** true quando o contexto falhou (painel não consegue montar). */
  isError: boolean;
}

const EMPTY_MOVEMENT: TvMovementSummary = {
  entradas: 0,
  saidas: 0,
  ultimaBipagem: null,
};

const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };

/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
function perdasSummaryFor(
  agg: PeriodedAggregates<PerdasByLoja> | undefined,
  lojaId: number,
): TvPerdasSummary {
  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
  const prev = agg?.previous.byLoja.get(lojaId);
  return {
    valor: cur.valor,
    itens: cur.itens,
    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
  };
}

/** Monta o resumo de compras de UMA unidade a partir dos agregados. */
function comprasSummaryFor(
  agg: PeriodedAggregates<ComprasByLoja> | undefined,
  lojaId: number,
): TvComprasSummary {
  const cur = agg?.current.byLoja.get(lojaId) ?? 0;
  const prev = agg?.previous.byLoja.get(lojaId);
  return { valor: cur, deltaPct: relativeDelta(cur, prev ?? null) };
}

/**
 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
 *
 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
 */
export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
  const tick = useMinuteClock();

  const ctxQuery = useQuery({
    queryKey: tvDashboardKeys.context(),
    queryFn: fetchTvContext,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });
  const ctx = ctxQuery.data;

  const liveQuery = useQuery({
    queryKey: tvDashboardKeys.liveSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLiveSales(ctx);
    },
    enabled: !!ctx,
    refetchInterval: TV_QUERY_INTERVALS.liveMs,
    staleTime: 30_000,
  });

  const laggedQuery = useQuery({
    queryKey: tvDashboardKeys.laggedSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLaggedSales(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const referenceQuery = useQuery({
    queryKey: tvDashboardKeys.referenceSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchDegustReference(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const perdasQuery = useQuery({
    queryKey: tvDashboardKeys.perdas(period),
    queryFn: () => fetchPerdasAggregates(period),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const comprasQuery = useQuery({
    queryKey: tvDashboardKeys.compras(period),
    queryFn: () => fetchComprasAggregates(period),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const feedQuery = useQuery({
    queryKey: tvDashboardKeys.movementFeed(),
    queryFn: fetchMovementFeed,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const metasQuery = useQuery({
    queryKey: tvDashboardKeys.metas(),
    queryFn: fetchMetas,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const stockQuery = useQuery({
    queryKey: tvDashboardKeys.stock(),
    queryFn: fetchStockAlerts,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const movementsQuery = useQuery({
    queryKey: tvDashboardKeys.movements(),
    queryFn: fetchMovementsToday,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const factoryQuery = useQuery({
    queryKey: tvDashboardKeys.factoryProduction(),
    queryFn: fetchFactoryProduction,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  return useMemo<TvDashboardData>(() => {
    const now = tick;
    const todayIso = toIsoDateLocal(now);
    const range = periodRange(period, now);
    const previousRange = previousPeriodRange(period, now);

    const stockDetail: Map<number, StockDetail> = buildStockSummary(
      stockQuery.data ?? [],
    );
    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
    const flashByLoja = new Map<number, FlashRow>(
      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
    );
    const laggedByLoja = new Map<number, LaggedSales>(
      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
    );
    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
    const perdasAgg = perdasQuery.data;
    const comprasAgg = comprasQuery.data;
    const lojaNomeById = new Map<number, string>(
      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
    );

    // ── Cards de loja ──
    const stores: TvStoreData[] = (ctx?.lojas ?? [])
      .filter((l) => !isFactoryTipo(l.tipo))
      .map((loja) => {
        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
          ? 'degust-live'
          : 'linx-lagged';
        const stock = stockDetail.get(loja.id);
        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;

        let vendas: TvSalesSnapshot | null = null;
        let metaDia: number | null = null;
        let pctMeta: number | null = null;
        let deltaSemana: number | null = null;
        let deltaOntem: number | null = null;

        if (channel === 'degust-live') {
          const flash = flashByLoja.get(loja.id);
          if (flash) {
            vendas = {
              valor: flash.total_vendas,
              cupons: flash.total_cupons,
              ticketMedio: flash.ticket_medio,
              dataReferencia: todayIso,
              isLive: true,
              caixaAberto: flash.caixa_aberto,
              atualizadoEm: flash.ultima_atualizacao,
            };
            metaDia = metaFor(metasQuery.data, loja.id, now);
            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
            // Deltas live = "vs MESMO PONTO do dia de referência": a base
            // (ontem = PRINCIPAL v3; semana passada = secundário) é
            // pró-rateada pela fração da janela já decorrida (mesma fração
            // do pró-rata da meta). Comparar hoje PARCIAL com dia COMPLETO
            // inflava a queda de manhã.
            deltaOntem = relativeDelta(
              flash.total_vendas,
              proRataDayBase(yesterdayByLoja.get(loja.id) ?? null, now),
            );
            deltaSemana = weekOverWeekDelta(
              flash.total_vendas,
              proRataDayBase(lastWeekByLoja.get(loja.id) ?? null, now),
            );
          }
        } else {
          const lagged = laggedByLoja.get(loja.id);
          if (lagged) {
            vendas = {
              valor: lagged.valor,
              cupons: null,
              ticketMedio: null,
              dataReferencia: lagged.dataReferencia,
              isLive: false,
              caixaAberto: null,
              atualizadoEm: null,
            };
            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
            const refDate = parseIsoDateLocal(lagged.dataReferencia);
            metaDia = metaFor(metasQuery.data, loja.id, refDate);
            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
            // Principal v3 = vs dia ANTERIOR ao de referência.
            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
            deltaSemana = weekOverWeekDelta(
              lagged.valor,
              lagged.valorSemanaAnterior,
            );
          }
        }

        const rag = classifyStoreRag({
          stockOutCount: stock?.zerados ?? 0,
          stockLowCount: stock?.abaixoMinimo ?? 0,
          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
          isLiveChannel: channel === 'degust-live',
          lastMovementAt: movement.ultimaBipagem,
          now,
        });

        return {
          lojaId: loja.id,
          nome: loja.nome,
          channel,
          vendas,
          metaDia,
          pctMeta,
          deltaSemana,
          deltaOntem,
          estoque: {
            zerados: stock?.zerados ?? 0,
            abaixoMinimo: stock?.abaixoMinimo ?? 0,
          },
          movimentacao: movement,
          perdas: perdasSummaryFor(perdasAgg, loja.id),
          compras: comprasSummaryFor(comprasAgg, loja.id),
          criticalItems: sortCriticalItems(stock?.itens ?? []),
          recentMoves: feedByLoja.get(loja.id) ?? [],
          rag: rag.status,
          ragReasons: rag.reasons,
        };
      });

    // ── Card da fábrica ──
    let factory: TvFactoryData | null = null;
    if (ctx?.factoryLojaId != null) {
      const fid = ctx.factoryLojaId;
      const stock = stockDetail.get(fid);
      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
      const rag = classifyStoreRag({
        stockOutCount: stock?.zerados ?? 0,
        stockLowCount: stock?.abaixoMinimo ?? 0,
        pctMetaProRata: null,
        isLiveChannel: false,
        lastMovementAt: movement.ultimaBipagem,
        now,
        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
        hours: TV_FACTORY_HOURS,
        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
      });
      factory = {
        lojaId: fid,
        nome: lojaNomeById.get(fid) ?? 'Fábrica',
        producao: factoryQuery.data ?? null,
        expedicoes: movement,
        estoque: {
          zerados: stock?.zerados ?? 0,
          abaixoMinimo: stock?.abaixoMinimo ?? 0,
        },
        perdas: perdasSummaryFor(perdasAgg, fid),
        compras: comprasSummaryFor(comprasAgg, fid),
        criticalItems: sortCriticalItems(stock?.itens ?? []),
        recentMoves: feedByLoja.get(fid) ?? [],
        rag: rag.status,
        ragReasons: rag.reasons,
      };
    }

    // ── Freshness ──
    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
    const freshness: TvFreshness = buildFreshness(
      liveQuery.dataUpdatedAt,
      stockQuery.dataUpdatedAt,
      TV_QUERY_INTERVALS,
      now,
    );

    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
    const allExceptions: TvException[] = buildStockExceptions(
      stockDetail,
      lojaNomeById,
    );
    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
    // janela), nunca por parsing de ragReasons — independe da cor do card
    // (aparece mesmo com card vermelho) e cobre também a fábrica.
    for (const store of stores) {
      const noMovement = buildNoMovementException({
        lojaId: store.lojaId,
        lojaNome: store.nome,
        lastMovementAt: store.movimentacao.ultimaBipagem,
        now,
      });
      if (noMovement) allExceptions.push(noMovement);
    }
    if (factory) {
      const noMovement = buildNoMovementException({
        lojaId: factory.lojaId,
        lojaNome: factory.nome,
        lastMovementAt: factory.expedicoes.ultimaBipagem,
        now,
        hours: TV_FACTORY_HOURS,
        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
      });
      if (noMovement) allExceptions.push(noMovement);
    }
    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
      const liveUpdatedAt = freshness.vendasLive.updatedAt;
      allExceptions.push({
        id: 'stale-data:vendas-live',
        kind: 'stale-data',
        severity: 'amber',
        lojaId: null,
        lojaNome: null,
        message: liveUpdatedAt
          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
          : 'Venda live ainda não carregou',
      });
    }
    const exceptions = sortAndLimitExceptions(allExceptions);

    // ── Hero (rede) ──
    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
    const liveStores = stores.filter(
      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
    );
    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
    const metasHoje = liveStores
      .map((s) => s.metaDia)
      .filter((m): m is number => m != null && m > 0);
    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
    const lastWeekTotal = liveStores.reduce(
      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
      0,
    );
    const yesterdayTotal = liveStores.reduce(
      (s, st) => s + (yesterdayByLoja.get(st.lojaId) ?? 0),
      0,
    );
    const network: TvNetworkSummary | null = ctx
      ? {
          vendasHoje,
          metaDia,
          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
          // Mesmo critério do card live: deltas "vs mesmo ponto do dia de
          // referência" (base pró-rateada pela fração da janela). Ontem é
          // o PRINCIPAL (v3); semana passada segue como secundário.
          deltaSemana: weekOverWeekDelta(
            vendasHoje,
            proRataDayBase(lastWeekTotal, now),
          ),
          deltaOntem: relativeDelta(
            vendasHoje,
            proRataDayBase(yesterdayTotal, now),
          ),
          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
          // nenhuma coluna — entram SOMENTE aqui).
          perdas: {
            valor: perdasAgg?.current.total.valor ?? 0,
            itens: perdasAgg?.current.total.itens ?? 0,
            deltaPct: relativeDelta(
              perdasAgg?.current.total.valor ?? 0,
              perdasAgg?.previous.total.valor ?? null,
            ),
          },
          compras: {
            valor: comprasAgg?.current.total ?? 0,
            deltaPct: relativeDelta(
              comprasAgg?.current.total ?? 0,
              comprasAgg?.previous.total ?? null,
            ),
          },
          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
          lojasLive: liveStores.length,
          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
        }
      : null;

    return {
      network,
      stores,
      factory,
      exceptions,
      freshness,
      period,
      range,
      previousRange,
      isLoading: ctxQuery.isLoading,
      isError: ctxQuery.isError,
    };
  }, [
    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
    // classificação congelaria no último snapshot de dados).
    tick,
    period,
    ctx,
    ctxQuery.isLoading,
    ctxQuery.isError,
    liveQuery.data,
    liveQuery.dataUpdatedAt,
    laggedQuery.data,
    referenceQuery.data,
    metasQuery.data,
    stockQuery.data,
    stockQuery.dataUpdatedAt,
    movementsQuery.data,
    feedQuery.data,
    perdasQuery.data,
    comprasQuery.data,
    factoryQuery.data,
  ]);
}

