1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	} from './types';
24	
25	// ─────────────────────────────────────────────────────────────────────────────
26	// Constantes de negócio
27	// ─────────────────────────────────────────────────────────────────────────────
28	
29	/**
30	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
31	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
32	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
33	 */
34	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };
35	
36	/**
37	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
38	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
39	 */
40	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
41	
42	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
43	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
44	
45	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
46	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
47	
48	/**
49	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
50	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
51	 */
52	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
53	
54	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
55	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
56	
57	/** Máximo de linhas exibidas na faixa de exceções. */
58	export const TV_EXCEPTIONS_LIMIT = 7;
59	
60	/** Itens do mini-feed "AGORA" por coluna de unidade. */
61	export const TV_MINI_FEED_SIZE = 3;
62	
63	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
64	export const TV_CRITICAL_TOP_N = 5;
65	
66	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
67	export const TV_DETAIL_FEED_LIMIT = 50;
68	
69	/**
70	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
71	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
72	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
73	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
74	 *
75	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
76	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
77	 * {@link isTvAlertSetor}.
78	 */
79	export const TV_ALERT_SETOR = 'PRODUTOS';
80	
81	// ─────────────────────────────────────────────────────────────────────────────
82	// Datas (helpers locais, sem dependência de timezone UTC)
83	// ─────────────────────────────────────────────────────────────────────────────
84	
85	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
86	export function toIsoDateLocal(d: Date): string {
87	  const y = d.getFullYear();
88	  const m = String(d.getMonth() + 1).padStart(2, '0');
89	  const day = String(d.getDate()).padStart(2, '0');
90	  return `${y}-${m}-${day}`;
91	}
92	
93	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
94	export function parseIsoDateLocal(iso: string): Date {
95	  const [y, m, d] = iso.split('-').map(Number);
96	  return new Date(y, (m ?? 1) - 1, d ?? 1);
97	}
98	
99	/** Soma `days` dias a uma data, retornando nova instância. */
100	export function addDays(d: Date, days: number): Date {
101	  const out = new Date(d);
102	  out.setDate(out.getDate() + days);
103	  return out;
104	}
105	
106	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
107	export function formatLaggedDateLabel(isoDate: string): string {
108	  const d = parseIsoDateLocal(isoDate);
109	  const dd = String(d.getDate()).padStart(2, '0');
110	  const mm = String(d.getMonth() + 1).padStart(2, '0');
111	  return `até ${dd}/${mm}`;
112	}
113	
114	/**
115	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
116	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
117	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
118	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
119	 */
120	export function parseBrDateTime(value: string | null | undefined): Date | null {
121	  if (!value) return null;
122	  const m = value.match(
123	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
124	  );
125	  if (m) {
126	    const [, dd, mm, yyyy, hh, mi, ss] = m;
127	    const month = Number(mm);
128	    const day = Number(dd);
129	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
130	    return new Date(
131	      Number(yyyy),
132	      month - 1,
133	      day,
134	      Number(hh),
135	      Number(mi),
136	      ss ? Number(ss) : 0,
137	    );
138	  }
139	  const fallback = new Date(value);
140	  return Number.isNaN(fallback.getTime()) ? null : fallback;
141	}
142	
143	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
144	export function timeHHMMFromIso(iso: string | null | undefined): string {
145	  if (!iso) return '—';
146	  const d = new Date(iso);
147	  if (Number.isNaN(d.getTime())) return '—';
148	  const hh = String(d.getHours()).padStart(2, '0');
149	  const mm = String(d.getMinutes()).padStart(2, '0');
150	  return `${hh}:${mm}`;
151	}
152	
153	// ─────────────────────────────────────────────────────────────────────────────
154	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
155	// ─────────────────────────────────────────────────────────────────────────────
156	
157	/**
158	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
159	 * - `today`: hoje → hoje;
160	 * - `week`: segunda-feira da semana corrente → hoje;
161	 * - `month`: dia 1º do mês corrente → hoje.
162	 */
163	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
164	  const today = toIsoDateLocal(now);
165	  if (period === 'today') return { from: today, to: today };
166	  if (period === 'week') {
167	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
168	    const dowFromMonday = (now.getDay() + 6) % 7;
169	    const monday = addDays(now, -dowFromMonday);
170	    return { from: toIsoDateLocal(monday), to: today };
171	  }
172	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
173	  return { from: toIsoDateLocal(firstOfMonth), to: today };
174	}
175	
176	/**
177	 * Período ANTERIOR equivalente para comparativos do filtro global:
178	 * - `today`: ontem → ontem;
179	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
180	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
181	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
182	 */
183	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
184	  if (period === 'today') {
185	    const yesterday = toIsoDateLocal(addDays(now, -1));
186	    return { from: yesterday, to: yesterday };
187	  }
188	  if (period === 'week') {
189	    const dowFromMonday = (now.getDay() + 6) % 7;
190	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
191	    return {
192	      from: toIsoDateLocal(mondayLastWeek),
193	      to: toIsoDateLocal(addDays(now, -7)),
194	    };
195	  }
196	  const y = now.getFullYear();
197	  const m = now.getMonth();
198	  const firstPrev = new Date(y, m - 1, 1);
199	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
200	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
201	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
202	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
203	}
204	
205	/**
206	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
207	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
208	 */
209	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
210	  const from = parseIsoDateLocal(range.from);
211	  const to = parseIsoDateLocal(range.to);
212	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
213	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
214	  return {
215	    from: toIsoDateLocal(addDays(from, -days)),
216	    to: toIsoDateLocal(addDays(to, -days)),
217	  };
218	}
219	
220	/**
221	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
222	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
223	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
224	 * (exclusivo — usar `.lt`, nunca `.lte`).
225	 */
226	export function rangeToLocalDayBounds(range: TvDateRange): {
227	  startIso: string;
228	  endExclusiveIso: string;
229	} {
230	  const start = parseIsoDateLocal(range.from);
231	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
232	  return {
233	    startIso: start.toISOString(),
234	    endExclusiveIso: endExclusive.toISOString(),
235	  };
236	}
237	
238	// ─────────────────────────────────────────────────────────────────────────────
239	// Pró-rata da meta
240	// ─────────────────────────────────────────────────────────────────────────────
241	
242	/**
243	 * Fração linear do dia comercial já decorrida em `now`.
244	 *
245	 * - Antes da abertura → 0 (não há venda esperada ainda).
246	 * - Depois do fechamento → 1 (meta integral esperada).
247	 * - Dentro da janela → interpolação linear simples (pró-rata).
248	 */
249	export function businessDayFraction(
250	  now: Date,
251	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
252	): number {
253	  const { start, end } = hours;
254	  if (end <= start) {
255	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
256	    return now.getHours() >= end ? 1 : 0;
257	  }
258	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
259	  if (h <= start) return 0;
260	  if (h >= end) return 1;
261	  return (h - start) / (end - start);
262	}
263	
264	/**
265	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
266	 *
267	 * Retorna null quando não dá para calcular com honestidade:
268	 * - meta ausente/zerada (sem referência), ou
269	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
270	 */
271	export function pctOfProRataTarget(
272	  sold: number,
273	  dailyTarget: number | null | undefined,
274	  now: Date,
275	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
276	): number | null {
277	  if (dailyTarget == null || dailyTarget <= 0) return null;
278	  const fraction = businessDayFraction(now, hours);
279	  if (fraction <= 0) return null;
280	  return (sold / (dailyTarget * fraction)) * 100;
281	}
282	
283	/**
284	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
285	 * cujo dia de referência já encerrou.
286	 */
287	export function pctOfFullDayTarget(
288	  sold: number,
289	  dailyTarget: number | null | undefined,
290	): number | null {
291	  if (dailyTarget == null || dailyTarget <= 0) return null;
292	  return (sold / dailyTarget) * 100;
293	}
294	
295	// ─────────────────────────────────────────────────────────────────────────────
296	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
297	// ─────────────────────────────────────────────────────────────────────────────
298	
299	/**
300	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
301	 * passada, período anterior do filtro…). Retorna null quando a base é
302	 * ausente ou não positiva — sem base honesta, sem número inventado.
303	 */
304	export function relativeDelta(
305	  current: number,
306	  base: number | null | undefined,
307	): number | null {
308	  if (base == null || base <= 0) return null;
309	  return ((current - base) / base) * 100;
310	}
311	
312	/**
313	 * Delta % vs MESMO DIA da semana anterior — caso particular de
314	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
315	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
316	 */
317	export function weekOverWeekDelta(
318	  current: number,
319	  lastWeek: number | null | undefined,
320	): number | null {
321	  return relativeDelta(current, lastWeek);
322	}
323	
324	/**
325	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
326	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
327	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
328	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
329	 * usada no pró-rata da meta, por consistência).
330	 *
331	 * Comparar dia parcial com dia completo inflava a queda de manhã.
332	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
333	 *
334	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
335	 * (fração 0 — não há ponto de comparação honesto).
336	 */
337	export function proRataDayBase(
338	  referenceDayTotal: number | null | undefined,
339	  now: Date,
340	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
341	): number | null {
342	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
343	  const fraction = businessDayFraction(now, hours);
344	  if (fraction <= 0) return null;
345	  return referenceDayTotal * fraction;
346	}
347	
348	/**
349	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
350	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
351	 * a API existente).
352	 */
353	export function proRataLastWeekBase(
354	  lastWeek: number | null | undefined,
355	  now: Date,
356	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
357	): number | null {
358	  return proRataDayBase(lastWeek, now, hours);
359	}
360	
361	// ─────────────────────────────────────────────────────────────────────────────
362	// RAG da loja
363	// ─────────────────────────────────────────────────────────────────────────────
364	
365	/** Entrada da classificação RAG de uma unidade. */
366	export interface StoreRagInput {
367	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
368	  stockOutCount: number;
369	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
370	  stockLowCount: number;
371	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
372	  pctMetaProRata: number | null;
373	  /** true quando a unidade tem venda ao vivo (canal Degust). */
374	  isLiveChannel: boolean;
375	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
376	  lastMovementAt: Date | string | null;
377	  /** Instante da avaliação. */
378	  now: Date;
379	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
380	  hours?: TvBusinessHours;
381	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
382	  noMovementThresholdHours?: number;
383	}
384	
385	/**
386	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
387	 *
388	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
389	 *   não faz sentido alertar madrugada sem bipagem.
390	 * - A referência é clampada ao início da janela de hoje: se a última
391	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
392	 */
393	export function hoursWithoutMovementInWindow(
394	  lastMovementAt: Date | string | null,
395	  now: Date,
396	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
397	): number | null {
398	  const fraction = businessDayFraction(now, hours);
399	  if (fraction <= 0 || fraction >= 1) return null;
400	  const windowStart = new Date(now);
401	  windowStart.setHours(hours.start, 0, 0, 0);
402	  const last = lastMovementAt
403	    ? new Date(lastMovementAt).getTime()
404	    : Number.NEGATIVE_INFINITY;
405	  const ref = Math.max(last, windowStart.getTime());
406	  return (now.getTime() - ref) / 3_600_000;
407	}
408	
409	/**
410	 * Classificação RAG de uma unidade (management-by-exception).
411	 *
412	 * Regras (design.md §1.6, ordem de precedência):
413	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
414	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
415	 *   manhã, quando o pró-rata ainda é instável).
416	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
417	 *   movimentação há mais que o threshold dentro da janela OU venda live com
418	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
419	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
420	 *   em canal live e com meta cadastrada (pct != null).
421	 * - OK: nenhum desvio — tela calma, sem cor.
422	 */
423	export function classifyStoreRag(input: StoreRagInput): {
424	  status: TvRagStatus;
425	  reasons: string[];
426	} {
427	  const hours = input.hours ?? TV_BUSINESS_HOURS;
428	  const noMovementThreshold =
429	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
430	  const reasons: string[] = [];
431	
432	  // ── Vermelho: só ruptura (item zerado em alerta) ──
433	  if (input.stockOutCount > 0) {
434	    reasons.push(
435	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
436	    );
437	    return { status: 'red', reasons };
438	  }
439	
440	  // ── Âmbar ──
441	  if (input.stockLowCount > 0) {
442	    reasons.push(
443	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
444	    );
445	  }
446	  const gapHours = hoursWithoutMovementInWindow(
447	    input.lastMovementAt,
448	    input.now,
449	    hours,
450	  );
451	  if (gapHours !== null && gapHours > noMovementThreshold) {
452	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
453	  }
454	  if (
455	    input.isLiveChannel &&
456	    input.pctMetaProRata !== null &&
457	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
458	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
459	  ) {
460	    reasons.push(
461	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
462	    );
463	  }
464	  if (reasons.length > 0) return { status: 'amber', reasons };
465	
466	  return { status: 'ok', reasons: [] };
467	}
