/**
 * @module features/tv-dashboard/model/tvMath
 *
 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
 * delta semanal, classificação RAG, formatação compacta de moeda,
 * staleness e agregações determinísticas usadas pelo hook de dados.
 *
 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
 */

import type {
  TvBusinessHours,
  TvCriticalItem,
  TvDateRange,
  TvException,
  TvExceptionsResult,
  TvFreshness,
  TvFreshnessLevel,
  TvPeriod,
  TvRagStatus,
  TvRecentMove,
  TvStockAlertItem,
} from './types';

// ─────────────────────────────────────────────────────────────────────────────
// Constantes de negócio
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
 */
export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };

/**
 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
 */
export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };

/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
export const NO_MOVEMENT_THRESHOLD_HOURS = 3;

/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;

/**
 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
 */
export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;

/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
export const LIVE_SALES_AMBER_FROM_HOUR = 11;

/** Máximo de linhas exibidas na faixa de exceções. */
export const TV_EXCEPTIONS_LIMIT = 7;

/** Itens do mini-feed "AGORA" por coluna de unidade. */
export const TV_MINI_FEED_SIZE = 3;

/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
export const TV_CRITICAL_TOP_N = 5;

/** Máximo de linhas do feed de movimentações no drill-down por loja. */
export const TV_DETAIL_FEED_LIMIT = 50;

/**
 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
 *
 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
 * {@link isTvAlertSetor}.
 */
export const TV_ALERT_SETOR = 'PRODUTOS';

// ─────────────────────────────────────────────────────────────────────────────
// Datas (helpers locais, sem dependência de timezone UTC)
// ─────────────────────────────────────────────────────────────────────────────

/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
export function toIsoDateLocal(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
export function parseIsoDateLocal(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, (m ?? 1) - 1, d ?? 1);
}

/** Soma `days` dias a uma data, retornando nova instância. */
export function addDays(d: Date, days: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + days);
  return out;
}

/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
export function formatLaggedDateLabel(isoDate: string): string {
  const d = parseIsoDateLocal(isoDate);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `até ${dd}/${mm}`;
}

/**
 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
 */
export function parseBrDateTime(value: string | null | undefined): Date | null {
  if (!value) return null;
  const m = value.match(
    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
  );
  if (m) {
    const [, dd, mm, yyyy, hh, mi, ss] = m;
    const month = Number(mm);
    const day = Number(dd);
    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
    return new Date(
      Number(yyyy),
      month - 1,
      day,
      Number(hh),
      Number(mi),
      ss ? Number(ss) : 0,
    );
  }
  const fallback = new Date(value);
  return Number.isNaN(fallback.getTime()) ? null : fallback;
}

/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
export function timeHHMMFromIso(iso: string | null | undefined): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
 * - `today`: hoje → hoje;
 * - `week`: segunda-feira da semana corrente → hoje;
 * - `month`: dia 1º do mês corrente → hoje.
 */
export function periodRange(period: TvPeriod, now: Date): TvDateRange {
  const today = toIsoDateLocal(now);
  if (period === 'today') return { from: today, to: today };
  if (period === 'week') {
    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
    const dowFromMonday = (now.getDay() + 6) % 7;
    const monday = addDays(now, -dowFromMonday);
    return { from: toIsoDateLocal(monday), to: today };
  }
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  return { from: toIsoDateLocal(firstOfMonth), to: today };
}

/**
 * Período ANTERIOR equivalente para comparativos do filtro global:
 * - `today`: ontem → ontem;
 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
 */
export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
  if (period === 'today') {
    const yesterday = toIsoDateLocal(addDays(now, -1));
    return { from: yesterday, to: yesterday };
  }
  if (period === 'week') {
    const dowFromMonday = (now.getDay() + 6) % 7;
    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
    return {
      from: toIsoDateLocal(mondayLastWeek),
      to: toIsoDateLocal(addDays(now, -7)),
    };
  }
  const y = now.getFullYear();
  const m = now.getMonth();
  const firstPrev = new Date(y, m - 1, 1);
  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
  const lastDayPrevMonth = new Date(y, m, 0).getDate();
  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
}

/**
 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
 */
export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
  const from = parseIsoDateLocal(range.from);
  const to = parseIsoDateLocal(range.to);
  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
  return {
    from: toIsoDateLocal(addDays(from, -days)),
    to: toIsoDateLocal(addDays(to, -days)),
  };
}

/**
 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
 * (exclusivo — usar `.lt`, nunca `.lte`).
 */
export function rangeToLocalDayBounds(range: TvDateRange): {
  startIso: string;
  endExclusiveIso: string;
} {
  const start = parseIsoDateLocal(range.from);
  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
  return {
    startIso: start.toISOString(),
    endExclusiveIso: endExclusive.toISOString(),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Pró-rata da meta
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fração linear do dia comercial já decorrida em `now`.
 *
 * - Antes da abertura → 0 (não há venda esperada ainda).
 * - Depois do fechamento → 1 (meta integral esperada).
 * - Dentro da janela → interpolação linear simples (pró-rata).
 */
export function businessDayFraction(
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number {
  const { start, end } = hours;
  if (end <= start) {
    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
    return now.getHours() >= end ? 1 : 0;
  }
  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
  if (h <= start) return 0;
  if (h >= end) return 1;
  return (h - start) / (end - start);
}

/**
 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
 *
 * Retorna null quando não dá para calcular com honestidade:
 * - meta ausente/zerada (sem referência), ou
 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
 */
export function pctOfProRataTarget(
  sold: number,
  dailyTarget: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  if (dailyTarget == null || dailyTarget <= 0) return null;
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0) return null;
  return (sold / (dailyTarget * fraction)) * 100;
}

/**
 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
 * cujo dia de referência já encerrou.
 */
export function pctOfFullDayTarget(
  sold: number,
  dailyTarget: number | null | undefined,
): number | null {
  if (dailyTarget == null || dailyTarget <= 0) return null;
  return (sold / dailyTarget) * 100;
}

// ─────────────────────────────────────────────────────────────────────────────
// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
 * passada, período anterior do filtro…). Retorna null quando a base é
 * ausente ou não positiva — sem base honesta, sem número inventado.
 */
export function relativeDelta(
  current: number,
  base: number | null | undefined,
): number | null {
  if (base == null || base <= 0) return null;
  return ((current - base) / base) * 100;
}

/**
 * Delta % vs MESMO DIA da semana anterior — caso particular de
 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
 */
export function weekOverWeekDelta(
  current: number,
  lastWeek: number | null | undefined,
): number | null {
  return relativeDelta(current, lastWeek);
}

/**
 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
 * usada no pró-rata da meta, por consistência).
 *
 * Comparar dia parcial com dia completo inflava a queda de manhã.
 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
 *
 * Retorna null quando a base é ausente/não positiva ou antes da abertura
 * (fração 0 — não há ponto de comparação honesto).
 */
export function proRataDayBase(
  referenceDayTotal: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0) return null;
  return referenceDayTotal * fraction;
}

/**
 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
 * a API existente).
 */
export function proRataLastWeekBase(
  lastWeek: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  return proRataDayBase(lastWeek, now, hours);
}

// ─────────────────────────────────────────────────────────────────────────────
// RAG da loja
// ─────────────────────────────────────────────────────────────────────────────

/** Entrada da classificação RAG de uma unidade. */
export interface StoreRagInput {
  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
  stockOutCount: number;
  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
  stockLowCount: number;
  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
  pctMetaProRata: number | null;
  /** true quando a unidade tem venda ao vivo (canal Degust). */
  isLiveChannel: boolean;
  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
  lastMovementAt: Date | string | null;
  /** Instante da avaliação. */
  now: Date;
  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
  hours?: TvBusinessHours;
  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
  noMovementThresholdHours?: number;
}

/**
 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
 *
 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
 *   não faz sentido alertar madrugada sem bipagem.
 * - A referência é clampada ao início da janela de hoje: se a última
 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
 */
export function hoursWithoutMovementInWindow(
  lastMovementAt: Date | string | null,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0 || fraction >= 1) return null;
  const windowStart = new Date(now);
  windowStart.setHours(hours.start, 0, 0, 0);
  const last = lastMovementAt
    ? new Date(lastMovementAt).getTime()
    : Number.NEGATIVE_INFINITY;
  const ref = Math.max(last, windowStart.getTime());
  return (now.getTime() - ref) / 3_600_000;
}

/**
 * Classificação RAG de uma unidade (management-by-exception).
 *
 * Regras (design.md §1.6, ordem de precedência):
 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
 *   manhã, quando o pró-rata ainda é instável).
 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
 *   movimentação há mais que o threshold dentro da janela OU venda live com
 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
 *   em canal live e com meta cadastrada (pct != null).
 * - OK: nenhum desvio — tela calma, sem cor.
 */
export function classifyStoreRag(input: StoreRagInput): {
  status: TvRagStatus;
  reasons: string[];
} {
  const hours = input.hours ?? TV_BUSINESS_HOURS;
  const noMovementThreshold =
    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
  const reasons: string[] = [];

  // ── Vermelho: só ruptura (item zerado em alerta) ──
  if (input.stockOutCount > 0) {
    reasons.push(
      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
    );
    return { status: 'red', reasons };
  }

  // ── Âmbar ──
  if (input.stockLowCount > 0) {
    reasons.push(
      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
    );
  }
  const gapHours = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    hours,
  );
  if (gapHours !== null && gapHours > noMovementThreshold) {
    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
  }
  if (
    input.isLiveChannel &&
    input.pctMetaProRata !== null &&
    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
  ) {
    reasons.push(
      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
    );
  }
  if (reasons.length > 0) return { status: 'amber', reasons };

  return { status: 'ok', reasons: [] };
}

/** Entrada de {@link buildNoMovementException}. */
export interface NoMovementExceptionInput {
  lojaId: number;
  lojaNome: string;
  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
  lastMovementAt: Date | string | null;
  now: Date;
  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
  hours?: TvBusinessHours;
  /** Threshold em horas (default lojas 3h; fábrica 2h). */
  thresholdHours?: number;
}

/**
 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
 * da última bipagem + janela), nunca por parsing de string de ragReasons —
 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
 * cobre também a fábrica (janela/threshold próprios via parâmetros).
 * Retorna null quando não há gap acima do threshold dentro da janela.
 */
export function buildNoMovementException(
  input: NoMovementExceptionInput,
): TvException | null {
  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
  const gap = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    input.hours ?? TV_BUSINESS_HOURS,
  );
  if (gap === null || gap <= threshold) return null;
  return {
    id: `no-movement:${input.lojaId}`,
    kind: 'no-movement',
    severity: 'amber',
    lojaId: input.lojaId,
    lojaNome: input.lojaNome,
    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
// ─────────────────────────────────────────────────────────────────────────────

function trimOneDecimal(v: number): string {
  const rounded = Math.round(v * 10) / 10;
  return rounded.toLocaleString('pt-BR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  });
}

/**
 * Formata um valor em BRL compacto para leitura a 3-5 metros:
 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
 * Valores negativos preservam o sinal ("-R$ 1,2k").
 */
export function formatCompactBRL(value: number): string {
  const sign = value < 0 ? '-' : '';
  const abs = Math.abs(value);
  // Bump pra M quando o arredondamento em k chegaria a 1000k
  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
  }
  if (abs >= 1_000) {
    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
  }
  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Staleness
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
 */
export function classifyStaleness(
  lastUpdatedAt: Date | string | number | null | undefined,
  expectedIntervalMs: number,
  now: Date,
): TvFreshnessLevel {
  if (lastUpdatedAt == null) return 'very-stale';
  const ts = new Date(lastUpdatedAt).getTime();
  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
  const age = now.getTime() - ts;
  if (age < 2 * expectedIntervalMs) return 'fresh';
  if (age < 6 * expectedIntervalMs) return 'stale';
  return 'very-stale';
}

/**
 * Monta o freshness consolidado a partir dos timestamps CRUS de última
 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
 *
 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
 * parar de avançar além de 2× o intervalo esperado.
 */
export function buildFreshness(
  liveUpdatedAtMs: number,
  stockUpdatedAtMs: number,
  intervals: { liveMs: number; slowMs: number },
  now: Date,
): TvFreshness {
  const liveUpdatedAt =
    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
  const stockUpdatedAt =
    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
  return {
    vendasLive: {
      updatedAt: liveUpdatedAt,
      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
      expectedIntervalMs: intervals.liveMs,
    },
    estoque: {
      updatedAt: stockUpdatedAt,
      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
      expectedIntervalMs: intervals.slowMs,
    },
    geradoEm: now.toISOString(),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Exceções — ordenação e corte
// ─────────────────────────────────────────────────────────────────────────────

const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
const KIND_ORDER: Record<string, number> = {
  'stock-out': 0,
  'stock-low': 1,
  'no-movement': 2,
  'stale-data': 3,
};

/**
 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
 * contagem do excedente.
 */
export function sortAndLimitExceptions(
  exceptions: TvException[],
  limit: number = TV_EXCEPTIONS_LIMIT,
): TvExceptionsResult {
  const sorted = [...exceptions].sort((a, b) => {
    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
    if (sev !== 0) return sev;
    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
    if (kind !== 0) return kind;
    return a.message.localeCompare(b.message, 'pt-BR');
  });
  return {
    items: sorted.slice(0, limit),
    overflowCount: Math.max(0, sorted.length - limit),
    totalCount: sorted.length,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Agregações determinísticas usadas pelo hook (puras, testáveis)
// ─────────────────────────────────────────────────────────────────────────────

/** Linha mínima de `movimentacoes` necessária à agregação. */
export interface MovementRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
}

/** Resultado por loja da agregação de movimentações do dia. */
export interface MovementAggregate {
  entradas: number;
  saidas: number;
  ultimaBipagem: string | null;
}

/**
 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
 * são ignoradas.
 */
export function aggregateMovements(
  rows: MovementRow[],
): Map<number, MovementAggregate> {
  const out = new Map<number, MovementAggregate>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    let agg = out.get(row.loja_id);
    if (!agg) {
      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
      out.set(row.loja_id, agg);
    }
    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
    if (
      row.data_movimentacao &&
      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
    ) {
      agg.ultimaBipagem = row.data_movimentacao;
    }
  }
  return out;
}

/**
 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
 * toda comparação de setor DEVE passar por aqui.
 */
export function normalizeSetor(value: string | null | undefined): string {
  return (value ?? '')
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .trim()
    .toLowerCase();
}

/**
 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
 */
export function isTvAlertSetor(setor: string | null | undefined): boolean {
  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
}

/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
export interface StockRow {
  loja_id: number | null;
  quantidade_atual: number | null;
  quantidade_minima: number | null;
  produtoNome: string;
  /** `produtos_master.setor` cru (caixa/acentos inconsistentes no banco). */
  setor: string | null;
}

/** Detalhe de alertas de estoque por loja. */
export interface StockDetail {
  zerados: number;
  abaixoMinimo: number;
  itens: TvStockAlertItem[];
}

/**
 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
 * query). Regras (critério existente do projeto, sem schema novo):
 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
 *   normalizada client-side porque a caixa no banco é inconsistente;
 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
 */
export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
  const out = new Map<number, StockDetail>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
    const min = row.quantidade_minima ?? 0;
    if (min <= 0) continue; // sem mínimo definido → sem alerta
    const qty = row.quantidade_atual ?? 0;
    if (qty >= min) continue; // dentro do normal
    let detail = out.get(row.loja_id);
    if (!detail) {
      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
      out.set(row.loja_id, detail);
    }
    const zerado = qty <= 0;
    if (zerado) detail.zerados += 1;
    else detail.abaixoMinimo += 1;
    detail.itens.push({
      produtoNome: row.produtoNome,
      quantidade: qty,
      quantidadeMinima: min,
      zerado,
    });
  }
  return out;
}

/**
 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
 */
export function buildStockExceptions(
  detailByLoja: Map<number, StockDetail>,
  lojaNomeById: Map<number, string>,
): TvException[] {
  const out: TvException[] = [];
  for (const [lojaId, detail] of detailByLoja) {
    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
    for (const item of detail.itens) {
      out.push({
        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
        kind: item.zerado ? 'stock-out' : 'stock-low',
        severity: item.zerado ? 'red' : 'amber',
        lojaId,
        lojaNome,
        message: item.zerado
          ? `${item.produtoNome} zerado — ${lojaNome}`
          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
        produtoNome: item.produtoNome,
        quantidade: item.quantidade,
        quantidadeMinima: item.quantidadeMinima,
      });
    }
  }
  return out;
}

/** Linha de venda live normalizada (resposta da edge `degust-pos-financial`). */
export interface FlashRow {
  loja_id: number;
  nome_loja: string;
  total_vendas: number;
  total_cupons: number;
  ticket_medio: number;
  caixa_aberto: boolean;
  ultima_atualizacao: string | null;
}

/**
 * Corrige o `loja_id` das linhas de flash-vendas.
 *
 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
 *
 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
 * - Caso contrário → descarta (não corromper outra loja).
 */
export function remapFlashLojaIds(
  rows: FlashRow[],
  degustCodeToLoja: ReadonlyMap<number, number>,
  knownDegustLojaIds: ReadonlySet<number>,
): FlashRow[] {
  const out: FlashRow[] = [];
  for (const row of rows) {
    if (knownDegustLojaIds.has(row.loja_id)) {
      out.push(row);
      continue;
    }
    const mapped = degustCodeToLoja.get(row.loja_id);
    if (mapped != null) {
      out.push({ ...row, loja_id: mapped });
    }
    // não mapeável → descartado de propósito (ver TSDoc)
  }
  return out;
}

/**
 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
 * o drill-down, a lista completa.
 */
export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
  const missingFraction = (c: TvCriticalItem): number =>
    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
  return items
    .map<TvCriticalItem>((i) => ({
      nome: i.produtoNome,
      quantidade: i.quantidade,
      minima: i.quantidadeMinima,
      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
    }))
    .sort((a, b) => {
      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
      const diff = missingFraction(b) - missingFraction(a);
      if (diff !== 0) return diff;
      return a.nome.localeCompare(b.nome, 'pt-BR');
    });
}

/** Linha mínima de `perdas` necessária à agregação por loja/rede. */
export interface PerdaAggRow {
  loja_id: number | null;
  valor_estimado: number | null;
}

/** Perdas agregadas (R$ + nº de registros). */
export interface PerdasAggregate {
  valor: number;
  itens: number;
}

/** Resultado da agregação de perdas: por loja + total da rede. */
export interface PerdasByLoja {
  byLoja: Map<number, PerdasAggregate>;
  /** Total da REDE — inclui linhas sem loja_id (fora de qualquer coluna). */
  total: PerdasAggregate;
}

/**
 * Agrega perdas do período: R$ (soma de `valor_estimado`, nulls contam 0 —
 * a perda EXISTE mesmo sem valor estimado e entra na contagem de itens) e
 * nº de registros, por loja e total da rede. Linhas sem loja_id entram
 * SOMENTE no total (não há coluna para atribuí-las).
 */
export function aggregatePerdas(rows: PerdaAggRow[]): PerdasByLoja {
  const byLoja = new Map<number, PerdasAggregate>();
  const total: PerdasAggregate = { valor: 0, itens: 0 };
  for (const row of rows) {
    const valor = row.valor_estimado ?? 0;
    total.valor += valor;
    total.itens += 1;
    if (row.loja_id == null) continue;
    let agg = byLoja.get(row.loja_id);
    if (!agg) {
      agg = { valor: 0, itens: 0 };
      byLoja.set(row.loja_id, agg);
    }
    agg.valor += valor;
    agg.itens += 1;
  }
  return { byLoja, total };
}

/** Linha mínima de `notas_fiscais` necessária à agregação de compras. */
export interface NotaAggRow {
  loja_id: number | null;
  valor_total: number | null;
}

/** Resultado da agregação de compras (NFs): por loja + total da rede. */
export interface ComprasByLoja {
  byLoja: Map<number, number>;
  /** Total da REDE — NFs com loja_id NULL entram SOMENTE aqui. */
  total: number;
}

/**
 * Agrega compras (NFs) do período: soma de `valor_total` por loja + total
 * da rede ("gasto até hoje"). NFs sem loja_id entram SOMENTE no total —
 * documentado no contrato (não há coluna para atribuí-las).
 */
export function aggregateCompras(rows: NotaAggRow[]): ComprasByLoja {
  const byLoja = new Map<number, number>();
  let total = 0;
  for (const row of rows) {
    const valor = row.valor_total ?? 0;
    total += valor;
    if (row.loja_id == null) continue;
    byLoja.set(row.loja_id, (byLoja.get(row.loja_id) ?? 0) + valor);
  }
  return { byLoja, total };
}

/** Linha do feed de movimentações (nome do produto já resolvido no fetch). */
export interface MovementFeedRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
  quantidade: number | null;
  produtoNome: string;
}

/** Converte uma linha crua do feed em {@link TvRecentMove} exibível. */
export function mapFeedRow(row: MovementFeedRow): TvRecentMove {
  return {
    hora: timeHHMMFromIso(row.data_movimentacao),
    timestamp: row.data_movimentacao,
    tipo: row.tipo_movimentacao,
    produtoNome: row.produtoNome,
    quantidade: row.quantidade ?? 0,
  };
}

/**
 * Agrupa o feed (já ordenado DESC por `data_movimentacao` na query) por
 * loja, mantendo as `perStore` primeiras linhas de cada uma (mini-feed
 * "AGORA"). Linhas sem loja são ignoradas. NÃO reordena — confia na
 * ordenação da query (única fonte do "mais recente primeiro").
 */
export function buildRecentMoves(
  rows: MovementFeedRow[],
  perStore: number = TV_MINI_FEED_SIZE,
): Map<number, TvRecentMove[]> {
  const out = new Map<number, TvRecentMove[]>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    let list = out.get(row.loja_id);
    if (!list) {
      list = [];
      out.set(row.loja_id, list);
    }
    if (list.length >= perStore) continue;
    list.push(mapFeedRow(row));
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
// ─────────────────────────────────────────────────────────────────────────────

/** Página de resultado mínima consumida por {@link fetchAllPages}. */
export interface TvPageResult<T> {
  data: T[] | null;
  error: { message: string } | null;
}

/**
 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
 *
 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
 * sobreporem entre requests.
 */
export async function fetchAllPages<T>(
  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
  pageSize = 1000,
): Promise<T[]> {
  const all: T[] = [];
  let offset = 0;
  for (;;) {
    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
    if (error) throw error;
    const rows = data ?? [];
    all.push(...rows);
    if (rows.length < pageSize) return all;
    offset += pageSize;
  }
}

