# Tentar pegar o token do Supabase CLI do Windows Credential Manager
try {
  $cred = [System.Net.CredentialCache]::DefaultNetworkCredentials
  # Tentar via cmdkey
  $creds = cmdkey /list 2>&1 | Select-String "Supabase"
  Write-Host "Supabase credentials found: $creds"

  # Tentar via Windows Vault
  $type = [System.Runtime.InteropServices.RuntimeEnvironment]
  Add-Type -AssemblyName System.Security
  $vaultType = 'Windows.Security.Credentials.PasswordVault' -as [type]
  Write-Host "Vault type: $vaultType"
} catch {
  Write-Host "Erro: $_"
}

# Alternativamente, procurar o token no perfil do usuario
$paths = @(
  "$env:USERPROFILE\.config\supabase\access-token",
  "$env:APPDATA\supabase\access-token",
  "$env:LOCALAPPDATA\supabase\config"
)
foreach ($p in $paths) {
  if (Test-Path $p) { Write-Host "Found: $p -> $(Get-Content $p -Raw -ErrorAction SilentlyContinue | Select-Object -First 1)" }
  else { Write-Host "Not found: $p" }
}

# Pegar o token do Windows Credential Manager
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;

public class CredentialManager {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CREDENTIAL {
        public int Flags;
        public int Type;
        public IntPtr TargetName;
        public IntPtr Comment;
        public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
        public int CredentialBlobSize;
        public IntPtr CredentialBlob;
        public int Persist;
        public int AttributeCount;
        public IntPtr Attributes;
        public IntPtr TargetAlias;
        public IntPtr UserName;
    }

    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool CredRead(string target, int type, int flags, out IntPtr credential);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern void CredFree(IntPtr credential);

    public static string GetCredential(string target) {
        IntPtr credPtr;
        if (CredRead(target, 1, 0, out credPtr)) {
            try {
                CREDENTIAL cred = Marshal.PtrToStructure<CREDENTIAL>(credPtr);
                return Marshal.PtrToStringUni(cred.CredentialBlob, cred.CredentialBlobSize / 2);
            } finally {
                CredFree(credPtr);
            }
        }
        return null;
    }
}
'@

$token = [CredentialManager]::GetCredential("Supabase CLI:access-token")
if ($token) {
    Write-Host "Token encontrado (primeiros 20 chars): $($token.Substring(0, [Math]::Min(20, $token.Length)))..."
    # Testar o token com a Management API para listar tabelas
    $proj = "jaumyfyeueayibbxunxc"
    $resp = Invoke-RestMethod -Uri "https://api.supabase.com/v1/projects/$proj/database/query" `
        -Method POST `
        -Headers @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" } `
        -Body '{"query": "SELECT column_name, data_type FROM information_schema.columns WHERE table_name = '\''degust_stores'\'' ORDER BY ordinal_position"}' `
        -ErrorAction SilentlyContinue
    if ($resp) { $resp | ConvertTo-Json } else { Write-Host "Query falhou" }
} else {
    Write-Host "Token nao encontrado"
}

Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;

public class CredMan {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CREDENTIAL {
        public int Flags; public int Type; public IntPtr TargetName;
        public IntPtr Comment; public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
        public int CredentialBlobSize; public IntPtr CredentialBlob;
        public int Persist; public int AttributeCount; public IntPtr Attributes;
        public IntPtr TargetAlias; public IntPtr UserName;
    }
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool CredRead(string target, int type, int flags, out IntPtr cred);
    [DllImport("advapi32.dll")] public static extern void CredFree(IntPtr cred);

    public static string GetAsUtf8(string target) {
        IntPtr ptr;
        if (!CredRead(target, 1, 0, out ptr)) return null;
        try {
            CREDENTIAL c = Marshal.PtrToStructure<CREDENTIAL>(ptr);
            byte[] bytes = new byte[c.CredentialBlobSize];
            Marshal.Copy(c.CredentialBlob, bytes, 0, c.CredentialBlobSize);
            return Encoding.UTF8.GetString(bytes);
        } finally { CredFree(ptr); }
    }
}
'@

$token = [CredMan]::GetAsUtf8("Supabase CLI:access-token")
Write-Host "Token (primeiros 30): $($token.Substring(0, [Math]::Min(30, $token.Length)))"

