public class CredMan2 {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CRED { public int F,T; public IntPtr TN,CM; public System.Runtime.InteropServices.ComTypes.FILETIME LW; public int BS; public IntPtr BB; public int P,AC; public IntPtr AT,TA,UN; }
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode)] public static extern bool CredRead(string t, int tp, int f, out IntPtr c);
    [DllImport("advapi32.dll")] public static extern void CredFree(IntPtr c);
    public static string Get(string t) {
        IntPtr p; if (!CredRead(t,1,0,out p)) return null;
        try { var c = Marshal.PtrToStructure<CRED>(p); var b = new byte[c.BS]; Marshal.Copy(c.BB,b,0,c.BS); return Encoding.UTF8.GetString(b); }
        finally { CredFree(p); }
    }
}
