async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
  const today = toIsoDateLocal(new Date());

  // Usa fetch direto (não supabase.functions.invoke) para evitar que o
  // sessionGuardFetch global intercepte um eventual 401 do edge function e
  // dispare SESSION_UNAUTHORIZED_EVENT cancelando a query silenciosamente.
  const supabaseUrl = (import.meta as Record<string, Record<string, string>>).env
    .VITE_SUPABASE_URL as string;
  const anonKey = (import.meta as Record<string, Record<string, string>>).env
    .VITE_SUPABASE_PUBLISHABLE_KEY as string;
  const session = (await supabase.auth.getSession()).data.session;
  const token = session?.access_token ?? anonKey;

  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      apikey: anonKey,
    },
    body: JSON.stringify({ startDate: today, endDate: today }),
  });

  if (!resp.ok) {
    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
  }

  const data = (await resp.json()) as DegustPosFinancialResponse;
  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
    loja_id: f.loja_id,
    nome_loja: f.nome_loja,
    total_vendas: f.total_vendas,
    total_cupons: f.total_cupons,
    ticket_medio: f.ticket_medio,
    caixa_aberto: f.caixa_aberto,
    ultima_atualizacao: f.ultima_atualizacao,
  }));
  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
}

