153	/**
154	 * Barra de meta FINA por coluna de loja: lógica idêntica ao hero, visual mais
155	 * compacto (h-1.5 lg:h-2) com label "XX% · esperado YY%" ao lado.
156	 */
157	export function TvColumnMetaBar({
158	  pctMetaProRata,
159	  metaDia,
160	  now,
161	}: {
162	  /** % pró-rata da meta do dia (pode ser null quando sem meta ou fora da janela). */
163	  pctMetaProRata: number | null;
164	  /** Meta do dia em R$ (null = sem meta cadastrada). */
165	  metaDia: number | null;
166	  now: Date;
167	}) {
168	  if (metaDia == null || metaDia <= 0) {
169	    return (
170	      <p className="mt-1 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] text-[#7C887E]">
171	        sem meta
172	      </p>
173	    );
174	  }
175	
176	  const fillPct = pctMetaProRata;
177	  const expectedPct = expectedPctNow(now);
178	  const ratio =
179	    fillPct != null && expectedPct > 0 ? fillPct / expectedPct : null;
180	  const color = metaBarColorFromRatio(ratio, now);
181	
182	  return (
183	    <div className="mt-1.5 flex items-center gap-2" data-testid="tv-col-meta-bar">
184	      <div className="relative flex-1 rounded-full bg-[#57715B]/10 h-1.5 lg:h-2">
185	        {fillPct != null && (
186	          <div
187	            className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${
188	              color === 'sage'
189	                ? 'bg-gradient-to-r from-[#57715B] to-[#4a6250]'
190	                : color === 'amber'
191	                  ? 'bg-gradient-to-r from-amber-400 to-amber-500'
192	                  : 'bg-gradient-to-r from-red-400 to-red-500'
193	            }`}
194	            style={{ width: `${Math.max(0, Math.min(100, fillPct))}%` }}
195	          />
196	        )}
197	        {expectedPct > 0 && (
198	          <div
199	            className="absolute rounded-full bg-[#C5A065]"
200	            style={{
201	              left: `calc(${Math.max(0, Math.min(100, expectedPct))}% - 1px)`,
202	              top: -3,
203	              width: 2,
204	              height: 14,
205	            }}
206	          />
207	        )}
208	      </div>
209	      <p className="shrink-0 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] tabular-nums text-[#7C887E]">
210	        {fillPct != null ? `${Math.round(fillPct)}%` : '—'}
211	        {' · esp. '}
212	        {expectedPct}%
213	      </p>
214	    </div>
215	  );
216	}
