141	  // Telas touch (sem hover) não disparam mousemove confiável — o botão
142	  // Metas fica SEMPRE visível, discreto no canto (design.md §8.4).
143	  const [isTouch] = useState(
144	    () =>
145	      typeof window !== 'undefined' &&
146	      typeof window.matchMedia === 'function' &&
