192	            ))}
193	          </div>
194	        </div>
195	      </div>
196	    );
197	  }
198	
199	  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);
200	
201	  // Em touch o botão Metas é permanente; com mouse, segue o ghost de 5s.
202	  const metasVisible = isTouch || controlsVisible;
203	
204	  return (
205	    <div
206	      className="relative min-h-dvh overflow-x-hidden bg-white font-momma text-[#2D362E] antialiased"
207	      data-testid="tv-dashboard"
208	    >
209	      <TvAmbience />
210	
211	      <div className="relative flex flex-col gap-4 p-4 sm:p-6 lg:gap-5 lg:px-6 lg:py-5">
212	        {/* Linha 0 — header mobile: botão voltar + título + botão metas */}
213	        <div className="flex items-center justify-between gap-3">
214	          <button
215	            type="button"
216	            onClick={() => navigate(-1)}
217	            className="flex items-center gap-1.5 rounded-full border border-[#57715B]/20 bg-white/70 px-3 py-1.5 font-momma text-sm font-medium text-[#57715B] backdrop-blur-sm transition-colors hover:bg-[#57715B]/10 lg:hidden"
218	            aria-label="Voltar"
219	          >
220	            <ArrowLeft className="h-4 w-4" aria-hidden />
221	            Voltar
222	          </button>
223	          <h1 className="hidden font-momma text-lg font-semibold text-[#2D362E] lg:block">
224	            Torre de Controle
225	          </h1>
226	          <button
227	            type="button"
228	            onClick={() => navigate('/tv/metas')}
229	            data-mia-action="abrir-metas-painel-tv"
230	            className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 font-momma text-sm font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
231	          >
232	            <Settings2 className="h-4 w-4" aria-hidden />
233	            Metas
234	          </button>
235	        </div>
236	
237	        {/* Linha 1 — hero (com filtro global Hoje/Semana/Mês) */}
238	        <TvHero
239	          network={data.network}
240	          freshness={data.freshness}
241	          now={now}
242	          period={period}
243	          onPeriodChange={setPeriod}
244	        />
245	
246	        {/* Linha 2 — colunas verticais de unidade (fábrica na posição 6) */}
247	        <div className="grid auto-rows-fr grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 lg:gap-5 xl:grid-cols-6 xl:gap-4">
248	          {data.isError ? (
249	            <>
250	              {Array.from({ length: 6 }, (_, i) => (
251	                <TvErrorCard key={i} />
