253	            </>
254	          ) : (
255	            <>
256	              {storeCards.map((store, idx) => (
257	                <div key={store.lojaId} className={`flex flex-col ${COL_ENTER_CLS[idx] ?? 'tv-col-enter tv-col-enter-1'}`}>
258	                  <TvStoreColumn
