import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import type { TvFreshness, TvStoreData } from '../model/types';
import TvDashboardPage from './TvDashboard.page';

const useTvDashboardDataMock = vi.hoisted(() => vi.fn());

vi.mock('../model/useTvDashboardData', async (importOriginal) => {
  const original =
    await importOriginal<typeof import('../model/useTvDashboardData')>();
  return { ...original, useTvDashboardData: useTvDashboardDataMock };
});

vi.mock('../model/useTvRealtime', () => ({ useTvRealtime: vi.fn() }));

const freshness: TvFreshness = {
  vendasLive: {
    updatedAt: new Date().toISOString(),
    level: 'fresh',
    expectedIntervalMs: 60_000,
  },
  estoque: {
    updatedAt: new Date().toISOString(),
    level: 'fresh',
    expectedIntervalMs: 300_000,
  },
  geradoEm: new Date().toISOString(),
};

function makeStore(lojaId: number, nome: string): TvStoreData {
  return {
    lojaId,
    nome,
    channel: 'degust-live',
    vendas: {
      valor: 1000 * lojaId,
      cupons: 10,
      ticketMedio: 30,
      dataReferencia: '2026-06-04',
      isLive: true,
      caixaAberto: true,
      atualizadoEm: null,
    },
    metaDia: null,
    pctMeta: null,
    deltaSemana: null,
    deltaOntem: 5,
    estoque: { zerados: 0, abaixoMinimo: 0 },
    movimentacao: { entradas: 1, saidas: 2, ultimaBipagem: null },
    perdas: { valor: 0, itens: 0, deltaPct: null },
    marketing: { valor: 0, acoes: 0, deltaPct: null },
    criticalItems: [],
    recentMoves: [],
    rag: 'ok',
    ragReasons: [],
  };
}

function dashboardData(period: 'today' | 'week' | 'month') {
  return {
    network: {
      vendasHoje: 9000,
      metaDia: null,
      pctMetaProRata: null,
      deltaSemana: null,
      deltaOntem: 3,
      perdas: { valor: 100, itens: 2, deltaPct: null },
      marketing: { valor: 500, acoes: 3, deltaPct: null },
      alertasCriticos: 0,
      lojasLive: 2,
      lojasDefasadas: 0,
    },
    stores: [makeStore(4, 'Momma Lago Sul'), makeStore(5, 'Momma Águas Claras')],
    factory: null,
    exceptions: { items: [], overflowCount: 0, totalCount: 0 },
    freshness,
    period,
    range: { from: '2026-06-04', to: '2026-06-04' },
    previousRange: { from: '2026-06-03', to: '2026-06-03' },
    isLoading: false,
    isError: false,
  };
}

beforeEach(() => {
  useTvDashboardDataMock.mockReset();
  useTvDashboardDataMock.mockImplementation((period: 'today' | 'week' | 'month') =>
    dashboardData(period ?? 'today'),
  );
});

function renderPage() {
  return render(
    <MemoryRouter initialEntries={['/tv']}>
      <TvDashboardPage />
    </MemoryRouter>,
  );
}

describe('TvDashboardPage v3 — colunas verticais', () => {
  it('renderiza uma coluna clicável por loja', () => {
    renderPage();
    expect(screen.getAllByTestId('tv-store-column')).toHaveLength(2);
    expect(screen.getByText('Momma Lago Sul')).toBeInTheDocument();
    expect(screen.getByText('Momma Águas Claras')).toBeInTheDocument();
  });

  it('a faixa de exceções/top produtos da v2 não existe mais', () => {
    renderPage();
    expect(screen.queryByTestId('tv-exceptions')).not.toBeInTheDocument();
    expect(screen.queryByTestId('tv-top-products')).not.toBeInTheDocument();
  });
});

describe('TvDashboardPage v3 — filtro global muda o period do hook', () => {
  it('inicia em "today" e repassa "week"/"month" ao useTvDashboardData', () => {
    renderPage();
    expect(useTvDashboardDataMock).toHaveBeenLastCalledWith('today');

    fireEvent.click(screen.getByRole('button', { name: 'Semana' }));
    expect(useTvDashboardDataMock).toHaveBeenLastCalledWith('week');

    fireEvent.click(screen.getByRole('button', { name: 'Mês' }));
    expect(useTvDashboardDataMock).toHaveBeenLastCalledWith('month');
  });
});

