/**
 * @module features/tv-dashboard/ui/TvChips
 *
 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
 * badge de estoque e barra de % meta com tick de esperado.
 * Linguagem v2 (glassmorphism Momma): design.md §1.3–§1.6, §3 e §4.
 * v2.1: tipografia fluida clamp() (referência a 1920px) e ícones em `em`
 * (escalam junto com o texto do chip).
 */

import {
  ArrowDown,
  ArrowUp,
  CalendarClock,
  Check,
  OctagonAlert,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import type {
  TvFreshnessLevel,
  TvRagStatus,
  TvSalesChannel,
  TvStockAlertSummary,
} from '../model/types';
import { formatLaggedDateLabel } from '../model/tvMath';
import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';

// ─────────────────────────────────────────────────────────────────────────────
// Delta comparativo (v3: principal = vs ONTEM; rótulo da base é genérico)
// ─────────────────────────────────────────────────────────────────────────────

interface TvDeltaChipProps {
  /** Delta % vs a base comparada. */
  delta: number;
  /** Rótulo da base comparada ("ontem", "dia ant.", "qua."). */
  label: string;
  /** Tamanho: hero (referência 28px a 1920px) ou card de loja (24px a 1920px). */
  size: 'hero' | 'card';
}

/**
 * Chip de delta comparativo. Neutro (pill sage suave) sempre — exceto delta
 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
 */
export function TvDeltaChip({ delta, label, size }: TvDeltaChipProps) {
  const isAlert = delta <= -15;
  const colorCls = isAlert
    ? 'bg-amber-50 text-amber-600'
    : 'bg-[#57715B]/8 text-[#5F6F63]';
  const textCls =
    size === 'hero'
      ? 'text-[clamp(0.875rem,1.45vw,2.625rem)]'
      : 'text-[clamp(0.8125rem,1.25vw,2.25rem)]';
  const Icon = delta < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 font-momma font-medium tabular-nums leading-none lg:px-4 lg:py-1.5 ${textCls} ${colorCls}`}
      data-testid="tv-delta-chip"
    >
      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {formatDeltaPct(delta)} vs {label}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de fonte (freshness honesta — design.md §4 item 1)
// ─────────────────────────────────────────────────────────────────────────────

interface TvSourceChipProps {
  channel: TvSalesChannel;
  /** Freshness da fonte live (ignorado para canal Linx). */
  liveLevel: TvFreshnessLevel;
  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
  laggedDate?: string | null;
}

/**

/**
 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
 * (defasagem esperada não é alarme).
 */
export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
  if (channel === 'linx-lagged') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-[#5F6F63]"
        data-testid="tv-source-chip-lagged"
      >
        <CalendarClock className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
      </span>
    );
  }
  if (liveLevel === 'fresh') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-emerald-600"
        data-testid="tv-source-chip-live"
      >
        <Check className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        ao vivo
      </span>
    );
  }
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600"
      data-testid="tv-source-chip-stale"
    >
      <RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
      atrasado
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de estado RAG (redundância não-cromática lível a 3m)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok.
 * Tem variantes dark (badge do design system) porque também é usado no
 * drill-down `/tv/loja/:id`, que roda DENTRO do DashboardLayout (tema livre).
 */
export function TvStateChip({ rag }: { rag: TvRagStatus }) {
  if (rag === 'ok') return null;
  if (rag === 'red') {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full bg-red-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-red-600 dark:bg-red-900/20"
        data-testid="tv-state-chip-red"
      >
        <OctagonAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
        CRÍTICO
      </span>
    );
  }
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-0.5 font-momma text-[clamp(0.75rem,1.05vw,1.875rem)] font-medium leading-none text-amber-600 dark:bg-amber-900/20"
      data-testid="tv-state-chip-amber"
    >
      <TriangleAlert className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />
      ATENÇÃO
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
 */

