import {
  ArrowDown,
  ArrowUp,
  CalendarClock,
  Check,
  OctagonAlert,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import type {
  TvFreshnessLevel,
  TvRagStatus,
  TvSalesChannel,
  TvStockAlertSummary,
} from '../model/types';

// ─────────────────────────────────────────────────────────────────────────────
// Live indicator — dot compacto substituindo o chip "ao vivo" (texto ruim)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Indicador de frescor minimalista: dot animado (live) ou dot estático
 * (stale/lagged). Usa cor + forma, não texto — compatível com WCAG 1.4.1
 * porque é sempre acompanhado do horário de atualização no mesmo elemento.
 */
export function TvLiveIndicator({
  channel,
  liveLevel,
}: {
  channel: TvSalesChannel;
  liveLevel: TvFreshnessLevel;
}) {
  if (channel === 'linx-lagged') {
    return (
      <CalendarClock
        className="h-3 w-3 shrink-0 text-[#9ca3af]"
        aria-label="dado defasado"
      />
    );
  }
  if (liveLevel === 'fresh') {
    return (
      <span
        className="inline-block h-2 w-2 shrink-0 rounded-full bg-emerald-400 animate-pulse"
        aria-label="ao vivo"
      />
    );
  }
  return (
    <span
      className="inline-block h-2 w-2 shrink-0 rounded-full bg-amber-400"
      aria-label="atualização atrasada"
    />
  );
}

