// Conversation repository — cross-device history via Supabase
// Fonte-de-verdade: chat_messages + mia_sessions. localStorage vira cache local.

import { supabase } from '@/integrations/supabase/client';
import type { MiaChatMessage } from '@/types/mia';

export interface ConversationMeta {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  messageCount: number;
}

interface ChatMessageRow {
  id: string;
  session_id: string;
  user_id: string;
  role: string;
  content: string;
  tool_calls: unknown;
  created_at: string;
}

interface SessionRow {
  id: string;
  title: string | null;
  created_at: string;
  last_activity_at: string;
  message_count: number;
}

const TITLE_FALLBACK = 'Nova conversa';

function rowToMessage(row: ChatMessageRow): MiaChatMessage | null {
  const role = row.role;
  if (role !== 'user' && role !== 'assistant') return null;
  return {
    id: row.id,
