async function fetchLiveSales(ctx: TvContext): Promise<LiveSalesResult> {
  const today = toIsoDateLocal(new Date());
  // Pedimos yesterday→today para receber também os totais de ontem via
  // ticket-medio — dado completo da API Degust, mais confiável que o
  // degust_vendas_diarias que pode ter sync parcial (cron 04:30).
  const yesterday = toIsoDateLocal(addDays(new Date(), -1));

  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
  const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;
  const session = (await supabase.auth.getSession()).data.session;
  const token = session?.access_token ?? anonKey;

  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      apikey: anonKey,
    },
    body: JSON.stringify({ startDate: yesterday, endDate: today }),
  });

  if (!resp.ok) {
    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
  }

  const data = (await resp.json()) as DegustPosFinancialResponse;

  const flash: FlashRow[] = remapFlashLojaIds(
    (data?.flash ?? []).map((f) => ({
      loja_id: f.loja_id,
      nome_loja: f.nome_loja,
      total_vendas: f.total_vendas,
      total_cupons: f.total_cupons,
      ticket_medio: f.ticket_medio,
      caixa_aberto: f.caixa_aberto,
      ultima_atualizacao: f.ultima_atualizacao,
    })),
    ctx.degustCodeToLoja,
    ctx.degustLojaIds,
  );

  // Extrair totais de ONTEM do breakdown diário (ticket-medio da API).
  // loja_id já remapeado pelo edge function; remapFlashLojaIds trata o resto.
  const yesterdayFromApi = new Map<number, number>();
  for (const d of data?.daily ?? []) {
    if (d.data === yesterday) {
      const lojaId = ctx.degustCodeToLoja.get(d.loja_id) ?? d.loja_id;
      if (ctx.degustLojaIds.has(lojaId)) {
        yesterdayFromApi.set(lojaId, (yesterdayFromApi.get(lojaId) ?? 0) + (d.total_faturado ?? 0));
      }
    }
  }

  return { flash, yesterdayFromApi };
}

