input.new_string:
/**
 * Retorno de fetchLiveSales:
 * - flash: dados ao vivo de hoje (ou último caixa fechado se madrugada)
 * - dailyByLoja: mapa loja_id → data → total_faturado (3 dias)
 *   Permite detectar a data real do flash e comparar vs dia anterior correto.
 */
interface LiveSalesResult {
  flash: FlashRow[];
  dailyByLoja: Map<number, Map<string, number>>;
}

async function fetchLiveSales(ctx: TvContext): Promise<LiveSalesResult> {
  const today = toIsoDateLocal(new Date());
  // Pedir 3 dias para lidar com a virada de meia-noite:
  // - hoje: Jun 11 (pode ter dados vazios se lojas ainda fechadas)
  // - ontem: Jun 10 (o flash pode mostrar esse dado a madrugada)
  // - anteontem: Jun 09 (base de comparação quando flash = Jun 10)
  const twoDaysAgo = toIsoDateLocal(addDays(new Date(), -2));

  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
  const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;
  const session = (await supabase.auth.getSession()).data.session;
  const token = session?.access_token ?? anonKey;

  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      apikey: anonKey,
    },
    body: JSON.stringify({ startDate: twoDaysAgo, endDate: today }),
  });

  if (!resp.ok) {
    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
  }

  const data = (await resp.json()) as DegustPosFinancialResponse;

  const flash: FlashRow[] = remapFlashLojaIds(
    (data?.flash ?? []).map((f) => ({
      loja_id: f.loja_id,
      nome_loja: f.nome_loja,
      total_vendas: f.total_vendas,
      total_cupons: f.total_cupons,
      ticket_medio: f.ticket_medio,
      caixa_aberto: f.caixa_aberto,
      ultima_atualizacao: f.ultima_atualizacao,
    })),
    ctx.degustCodeToLoja,
    ctx.degustLojaIds,
  );

  // Mapa loja_id → data → total via ticket-medio (dados completos por dia).
  // edge function v20 já remapeia codigoLoja → loja_id interno.
  const dailyByLoja = new Map<number, Map<string, number>>();
  for (const d of data?.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    let byDate = dailyByLoja.get(d.loja_id);
    if (!byDate) { byDate = new Map<string, number>(); dailyByLoja.set(d.loja_id, byDate); }
    byDate.set(d.data, (byDate.get(d.data) ?? 0) + (d.total_faturado ?? 0));
  }

  return { flash, dailyByLoja };
}

