import { createElement, type ReactNode } from 'react';
import { renderHook, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi } from 'vitest';
import {
  TV_QUERY_INTERVALS,
  tvDashboardKeys,
  useTvDashboardData,
} from './useTvDashboardData';

// Mock leve do client Supabase: builder encadeável thenable que resolve
// sempre { data: [], error: null } e edge function com flash vazio.
vi.mock('@/integrations/supabase/client', () => {
  type QueryResult = { data: never[]; error: null };
  const CHAIN_METHODS = [
    'select',
    'eq',
    'gt',
    'gte',
    'lt',
    'lte',
    'in',
    'or',
    'is',
    'not',
    'order',
    'limit',
    'range',
  ] as const;

  const makeBuilder = (): Record<string, unknown> => {
    const builder: Record<string, unknown> = {};
    for (const method of CHAIN_METHODS) {
      builder[method] = () => builder;
    }
    builder.then = (onFulfilled: (value: QueryResult) => unknown) =>
      Promise.resolve({ data: [] as never[], error: null }).then(onFulfilled);
    return builder;
  };

  return {
    supabase: {
      from: () => makeBuilder(),
      functions: {
        invoke: async () => ({ data: { flash: [] }, error: null }),
      },
    },
  };
});

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

describe('useTvDashboardData', () => {
  it('monta snapshot consolidado vazio sem crash (estado vazio confirmado)', async () => {
    const { result, unmount } = renderHook(() => useTvDashboardData(), {
      wrapper: createWrapper(),
    });

    expect(result.current.isLoading).toBe(true);

    await waitFor(() => expect(result.current.network).not.toBeNull());

    expect(result.current.isError).toBe(false);
    expect(result.current.stores).toEqual([]);
    expect(result.current.factory).toBeNull();
    // Estado vazio de exceções explícito (spec: "Nenhum alerta")
    expect(result.current.exceptions.items).toEqual([]);
    expect(result.current.exceptions.totalCount).toBe(0);
    expect(result.current.exceptions.overflowCount).toBe(0);
    // Rede sem lojas → tudo zerado/nulo, sem divisão por zero
    expect(result.current.network).toMatchObject({
      vendasHoje: 0,
      metaDia: null,
      pctMetaProRata: null,
      deltaSemana: null,
      deltaOntem: null,
      perdas: { valor: 0, itens: 0, deltaPct: null },
      marketing: { valor: 0, acoes: 0, deltaPct: null },
      alertasCriticos: 0,
      lojasLive: 0,
      lojasDefasadas: 0,
    });
    // Filtro global default = hoje, com range anterior equivalente (ontem)
    expect(result.current.period).toBe('today');
    expect(result.current.range.from).toBe(result.current.range.to);
    expect(result.current.previousRange.from).toBe(
      result.current.previousRange.to,
    );
    // Freshness sempre presente com timestamp de geração
    expect(result.current.freshness.geradoEm).toBeTruthy();
    expect(result.current.freshness.vendasLive.expectedIntervalMs).toBe(
      TV_QUERY_INTERVALS.liveMs,
    );

    unmount();
  });

  it('aceita o filtro global de período e o ecoa no snapshot', async () => {
    const { result, unmount } = renderHook(() => useTvDashboardData('month'), {
      wrapper: createWrapper(),
    });
    await waitFor(() => expect(result.current.network).not.toBeNull());
    expect(result.current.period).toBe('month');
    // Mês corrente começa no dia 1º
    expect(result.current.range.from.endsWith('-01')).toBe(true);
    unmount();
  });

  it('expõe query keys estáveis sob o prefixo tv-dashboard', () => {
    expect(tvDashboardKeys.all).toEqual(['tv-dashboard']);
    expect(tvDashboardKeys.stock()[0]).toBe('tv-dashboard');
    expect(tvDashboardKeys.movements()[0]).toBe('tv-dashboard');
    expect(tvDashboardKeys.liveSales()[0]).toBe('tv-dashboard');
    // v3: perdas/marketing keyed por período sob o MESMO prefixo raiz
    expect(tvDashboardKeys.perdas('week')).toEqual([
      'tv-dashboard',
      'perdas',
      'week',
    ]);
    expect(tvDashboardKeys.marketing('month')).toEqual([
      'tv-dashboard',
      'marketing',
      'month',
    ]);
    expect(tvDashboardKeys.movementFeed()[0]).toBe('tv-dashboard');
    expect(
      tvDashboardKeys.storeDetail(4, { from: '2026-06-01', to: '2026-06-04' }),
    ).toEqual(['tv-dashboard', 'store-detail', 4, '2026-06-01', '2026-06-04']);
  });
});

import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { TvHero } from './TvHero';
import type { TvFreshness, TvNetworkSummary } from '../model/types';

// qui 04/06/2026, 14:30 — dentro da janela comercial
const NOW = new Date(2026, 5, 4, 14, 30);

const network: TvNetworkSummary = {
  vendasHoje: 21_300,
  metaDia: 30_000,
  pctMetaProRata: 110,
  deltaSemana: 5,
  deltaOntem: 12,
  perdas: { valor: 480, itens: 7, deltaPct: 25 },
  marketing: { valor: 5_200, acoes: 12, deltaPct: -10 },
  alertasCriticos: 2,
  lojasLive: 3,
  lojasDefasadas: 2,
};

const freshness: TvFreshness = {
  vendasLive: {
    updatedAt: new Date(2026, 5, 4, 14, 29).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 60_000,
  },
  estoque: {
    updatedAt: new Date(2026, 5, 4, 14, 25).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 300_000,
  },
  geradoEm: NOW.toISOString(),
};

function renderHero(period: 'today' | 'week' | 'month' = 'today') {
  const onPeriodChange = vi.fn();
  render(
    <TvHero
      network={network}
      freshness={freshness}
      now={NOW}
      period={period}
      onPeriodChange={onPeriodChange}
    />,
  );
  return { onPeriodChange };
}

describe('TvHero v3 — métricas da rede', () => {
  it('mostra vendas de hoje + delta principal vs ONTEM', () => {
    renderHero();
    expect(screen.getByTestId('tv-hero-sales')).toHaveTextContent('R$ 21,3k');
    // hero tem 2 chips: deltaOntem (primeiro) + deltaSemana
    expect(screen.getAllByTestId('tv-delta-chip')[0]).toHaveTextContent('12% vs ontem');
  });

  it('mostra marketing e perdas do período com rótulo do filtro', () => {
    renderHero();
    expect(screen.getByText('MARKETING · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-marketing')).toHaveTextContent('R$ 5,2k');
    expect(screen.getByText('PERDAS · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('R$ 480');
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('7 itens');
  });

  it('rótulo das métricas acompanha o período selecionado', () => {
    renderHero('month');
    expect(screen.getByText('MARKETING · mês')).toBeInTheDocument();
    expect(screen.getByText('PERDAS · mês')).toBeInTheDocument();
  });

  it('barra de meta segue presente como secundária', () => {
    renderHero();
    expect(screen.getByTestId('tv-meta-bar')).toBeInTheDocument();
    expect(screen.getByText(/71% da meta/)).toBeInTheDocument();
  });
});

describe('TvHero v3 — filtro global Hoje/Semana/Mês', () => {
  it('dispara onPeriodChange ao clicar em outro período', () => {
    const { onPeriodChange } = renderHero();
    fireEvent.click(screen.getByRole('button', { name: 'Semana' }));
    expect(onPeriodChange).toHaveBeenCalledWith('week');
    fireEvent.click(screen.getByRole('button', { name: 'Mês' }));
    expect(onPeriodChange).toHaveBeenCalledWith('month');
  });

  it('marca o período ativo com aria-pressed', () => {
    renderHero('week');
    expect(screen.getByRole('button', { name: 'Semana' })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    expect(screen.getByRole('button', { name: 'Hoje' })).toHaveAttribute(
      'aria-pressed',
      'false',
    );
  });
});

