/**
 * @module PermissionBlur
 *
 * Componente de proteção visual por permissão.
 * Renderiza o conteúdo com blur e overlay de "Acesso Negado" quando
 * o usuário não possui permissão para o módulo solicitado.
 */

import React from 'react';
import { AlertTriangle, ArrowLeft } from 'lucide-react';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import { Button } from '@/shared/ui/button';
import { useNavigate } from 'react-router-dom';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { usePermissions } from '@/shared/hooks/usePermissions';

interface PermissionBlurProps {
  children: React.ReactNode;
  hasPermission: boolean;
  moduleName?: string;
  permissionName?: string;
  loading?: boolean;
}

export const PermissionBlur: React.FC<PermissionBlurProps> = ({
  children,
  hasPermission,
  moduleName = 'esta funcionalidade',
  permissionName,
  loading: loadingProp,
}) => {
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const { loading: permissionsLoading } = usePermissions();

  // Enquanto permissões estão carregando, renderizar conteúdo normalmente
  // Evita flash de "Acesso Negado" em redes lentas (especialmente mobile)
  const isLoading = loadingProp ?? permissionsLoading;
  if (isLoading) {
    return <>{children}</>;
  }

  if (!hasPermission) {
    return (
      <div className="relative min-h-screen">
        {/* Conteúdo com blur */}
        <div className="filter blur-md pointer-events-none select-none">
          {children}
        </div>

        {/* Overlay com mensagem de acesso negado */}
        <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-50">
          {isMobile && (
            <Button
              variant="ghost"
              size="icon"
              onClick={() => navigate('/dashboard')}
              className="absolute top-4 left-4 h-10 w-10 rounded-full bg-white/80 text-foreground shadow-sm"
              aria-label="Voltar para início"
            >
              <ArrowLeft className="h-5 w-5" />
            </Button>
          )}
          <div className="bg-white dark:bg-gray-800 p-8 rounded-lg shadow-2xl max-w-md mx-4 text-center">
            <div className="flex justify-center mb-4">
              <AlertTriangle className="h-16 w-16 text-red-500" />
            </div>

            <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-4">
              Acesso Negado
            </h2>

            <Alert className="mb-6 border-red-200 bg-red-50 dark:bg-red-900/20">
              <AlertTriangle className="h-4 w-4 text-red-600" />
              <AlertDescription className="text-red-800 dark:text-red-200">
                Você não tem acesso ao módulo {moduleName} para acessar isso.
                {permissionName && (
                  <span className="block mt-2 text-sm">
                    Permissão necessária:{' '}
                    <code className="bg-red-100 dark:bg-red-800 px-1 py-0.5 rounded text-xs">
                      {permissionName}
                    </code>
                  </span>
                )}
              </AlertDescription>
            </Alert>

            <div className="space-y-3">
              <p className="text-gray-600 dark:text-gray-300 text-sm">
                Entre em contato com o administrador do sistema para solicitar
                acesso a esta funcionalidade.
              </p>

              <div className="flex gap-3 justify-center">
                <Button
                  variant="outline"
                  onClick={() => navigate(-1)}
                  className="flex-1"
                >
                  Voltar
                </Button>
                <Button
                  onClick={() => navigate('/dashboard')}
                  className="flex-1"
                >
                  Dashboard
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return <>{children}</>;
};

export default PermissionBlur;

